#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long pow_mod(long long base, long long exp) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long cmb(int a, int b, vector<long long>& fact, vector<long long>& revFact) {
    if (a < b) return 0;
    return (((fact[a] * revFact[b]) % mod) * revFact[a - b]) % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long tmp;
    cin >> n >> tmp;
    if (n <= tmp) {
        cout << 0 << "\n";
        return 0;
    }
    int k = (int)tmp;
    vector<long long> fact(400001, 1);
    vector<long long> revFact(400001);
    for (int i = 1; i <= 400000; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
    revFact[400000] = pow_mod(fact[400000], mod - 2);
    for (int i = 399999; i >= 0; i--) {
        revFact[i] = (revFact[i + 1] * (i + 1)) % mod;
    }
    long long totalComb = cmb(n, n - k, fact, revFact);
    long long answer = 0;
    int sign = 1;
    for (int i = n - k; i >= 1; i--) {
        long long term = cmb(n - k, i, fact, revFact);
        long long val = pow_mod(i, n);
        answer = (answer + sign * term % mod * val % mod) % mod;
        sign *= -1;
    }
    answer = (answer * totalComb) % mod;
    if (k != 0) answer = (answer * 2) % mod;
    cout << (answer + mod) % mod << "\n";
    return 0;
}
